<template><view class="vp-result"><view class="vp-result__card"><view class="vp-result__header"><view><text class="vp-result__title">{{ completed?'训练完成':'训练未完成' }}</text><text class="vp-result__sub">{{ completed?'公园活力已提升':'已保留当前训练数据' }}</text></view><text class="vp-result__event">激活 {{ game.activatedEventCount }}/10 个事件</text></view><view class="vp-result__columns"><view class="vp-result__section"><text class="vp-result__section-title">康复训练数据</text><view class="vp-result__grid"><view><text>有效次数</text><strong>{{ training.total_count }}</strong></view><view><text>训练组数</text><strong>{{ training.set_index }}/{{ training.target_sets }}</strong></view><view><text>最大 ROM</text><strong>{{ fmt(training.max_rom_deg) }}°</strong></view><view><text>整体完成度</text><strong>{{ training.overall_completion_percent }}%</strong></view><view><text>总用时</text><strong>{{ seconds(elapsedMs) }}秒</strong></view><view><text>有效训练</text><strong>{{ seconds(activeElapsedMs) }}秒</strong></view></view></view><view class="vp-result__section vp-result__section--game"><text class="vp-result__section-title">公园活力数据</text><text class="vp-result__value">{{ game.vitalityValue }}<small> 活力值</small></text><view class="vp-result__row"><text>激活事件</text><strong>{{ game.activatedEventCount }} 个</strong></view><view class="vp-result__row"><text>最大连续完成</text><strong>{{ game.bestCombo }}</strong></view><view class="vp-result__row"><text>场景状态</text><strong>{{ game.celebration?'庆祝中':'持续生长' }}</strong></view></view></view><view class="vp-result__actions"><button @click="again">再练一次</button><button class="vp-result__back" @click="back">返回活力公园</button></view></view></view></template>
<script lang="ts">
import { appendReturnUrl, configureCallerReturnUrl, getCallerReturnUrl, returnToCaller } from '../../game-platform/runtime/navigation'
import { consumeVitalityResult, prepareVitalityReplay } from '../runtime/session-runtime'
import type { VitalityTrainingResult } from '../types/result'
const empty:VitalityTrainingResult={gameId:'vitality-park',endReason:'STOPPED',elapsedMs:0,activeElapsedMs:0,completedAtMs:0,training:{left_count:0,right_count:0,left_rom_deg:0,right_rom_deg:0,lr_rom_diff_deg:0,target_count:10,completion_percent:0,training_state:'STOPPED',set_index:1,target_sets:1,overall_completion_percent:0,total_count:0,max_rom_deg:0,total_sets:1},game:{activatedEventCount:0,vitalityValue:0,combo:0,bestCombo:0,celebration:false}}
export default {name:'VitalityParkResult',data(){return{result:null as VitalityTrainingResult|null,training:{...empty.training},game:{...empty.game},elapsedMs:0,activeElapsedMs:0,endReason:'STOPPED' as 'FINISHED'|'STOPPED'}},computed:{completed():boolean{return this.endReason==='FINISHED'}},onLoad(query:Record<string,string|undefined>){configureCallerReturnUrl(query?.returnUrl,'/pages-vitality-park/home/index');const value=consumeVitalityResult();if(value){this.result=value;this.training={...value.training};this.game={...value.game};this.elapsedMs=value.elapsedMs;this.activeElapsedMs=value.activeElapsedMs;this.endReason=value.endReason}},onBackPress(){this.back();return true},methods:{fmt(v:number){return Number(v||0).toFixed(1)},seconds(v:number){return Math.round(v/1000)},again(){prepareVitalityReplay();uni.redirectTo({url:appendReturnUrl('/pages-vitality-park/prepare/index')})},back(){returnToCaller({returnUrl:getCallerReturnUrl()})}}}
</script>
<style scoped>
.vp-result{box-sizing:border-box;display:flex;align-items:center;justify-content:center;width:100vw;height:100vh;min-height:260px;padding:12px;background:linear-gradient(145deg,#dff6dc,#fff3c3);font-family:"Microsoft YaHei",sans-serif;color:#315b36;overflow:auto}.vp-result__card{width:min(900px,94vw);box-sizing:border-box;padding:18px 24px;border:3px solid #70ae52;border-radius:22px;background:#fff;box-shadow:0 8px 0 rgba(52,105,42,.16)}.vp-result__header{display:flex;align-items:center;justify-content:space-between;border-bottom:2px solid #d7e9ce;padding-bottom:9px}.vp-result__title,.vp-result__sub{display:block}.vp-result__title{color:#2d823b;font-size:34px;font-weight:900}.vp-result__sub{margin-top:3px;color:#71816c;font-size:13px}.vp-result__event{padding:7px 10px;border-radius:999px;background:#eff9e8;color:#559044;font-weight:900}.vp-result__columns{display:grid;grid-template-columns:1.5fr 1fr;gap:14px;margin-top:12px}.vp-result__section{padding:12px;border-radius:14px;background:#f3faee}.vp-result__section--game{background:#fff8dc}.vp-result__section-title{font-size:18px;font-weight:900}.vp-result__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:7px;margin-top:8px}.vp-result__grid view{display:flex;flex-direction:column;padding:7px;border-radius:9px;background:#fff;font-size:12px}.vp-result__grid strong{margin-top:2px;font-size:22px}.vp-result__value{display:block;color:#d88416;text-align:center;font-size:42px;font-weight:900}.vp-result__value small{font-size:15px}.vp-result__row{display:flex;justify-content:space-between;padding:6px 4px;border-bottom:1px solid #eadca7;font-size:13px}.vp-result__actions{display:flex;justify-content:center;gap:14px;margin-top:13px}.vp-result__actions button{display:flex;align-items:center;justify-content:center;width:190px;height:44px;margin:0;border:0;border-radius:999px;background:#5ab72d;color:#fff;font-size:17px;font-weight:900}.vp-result__actions .vp-result__back{background:#4c9fd0}@media(max-width:560px){.vp-result{align-items:flex-start}.vp-result__card{width:calc(100vw - 20px);padding:14px}.vp-result__header{align-items:flex-start;gap:8px}.vp-result__title{font-size:28px}.vp-result__event{font-size:11px}.vp-result__columns{display:flex;flex-direction:column;gap:8px}.vp-result__grid{grid-template-columns:repeat(2,minmax(0,1fr))}.vp-result__actions{gap:8px}.vp-result__actions button{flex:1;width:auto;font-size:15px}}
</style>
